import json
from pathlib import Path
pages={p['page']:p['flat'] for p in map(json.loads,Path('out/index/pages.jsonl').read_text().splitlines())}
claims=[]
def fact(i,s,p,q,cond='',v=None):
 assert q in pages[p],(i,q)
 claims.append(dict(id=i,**{'class':'FACT'},statement=s,value=v,page=p,source='表1及第4–6节' if p>=4 else '摘要及第2–4节',quote=q,conditions=cond))
def infer(i,s,p,q,r):
 assert q in pages[p]
 claims.append(dict(id=i,**{'class':'INFERRED'},statement=s,value=None,page=p,source='面向课程条件的适配推断',quote=q,reasoning=r))
fact('C1','文章定位是中等规模的监督与无监督学习，强调易用性、文档、性能和API一致性。',2,'Scikit-learn is a Python module integrating a wide range of state-of-the-art machine learning algorithms for medium-scale supervised and unsupervised problems.','2011年作者对项目定位的描述，不能等同任意规模的容量保证。')
fact('C2','数据容器依赖NumPy数组；输入以NumPy数组呈现。',3,'Input data is presented as numpy arrays, thus integrating seamlessly with other scientific Python libraries.','课程表格需转为适合算法的数值表示；文章未提供课程数据的编码方案。')
fact('C3','接口靠约定而非强制继承；estimator的fit接收输入数据数组，监督问题还可接收标签数组。',3,'To facilitate the use of external objects with scikit-learn, inheritance is not enforced; instead, code conventions provide a consistent interface. The central object is an estimator, that implements a fit method, accepting as arguments an input data array and, optionally, an array of labels for supervised problems.')
fact('C4','监督估计器可提供predict；transformer是提供transform、返回修改后输入数据的估计器，例如PCA。这些方法并非每个估计器都必须全部具有。',3,'Supervised estimators, such as SVM classifiers, can implement a predict method. Some estimators, that we call transformers, for example, PCA, implement a transform method, returning modified input data.')
fact('C5','score可用于评价拟合优度，约定越大越好，例如对数似然或负损失；不能把不同任务的score自动当成同一种可比指标。',4,'may also provide a score method, which is an increasing evaluation of goodness of fit: a loglikelihood, or a negated loss function.','后半句为指标口径限制的解释；原文未声称所有score具有同一统计含义。')
fact('C6','交叉验证迭代器产生训练、测试索引对，可用K折、留一或分层划分。',4,'The other important object is the cross-validation iterator, which provides pairs of train and test indices to split input data, for example K-fold, leave one out, or stratified cross-validation.')
fact('C7','GridSearchCV包装估计器，通过交叉验证评价/选参，可选多核计算；fit遍历指定参数网格，以底层估计器score最大化为准则。',4,'Scikit-learn can evaluate an estimator’s performance or select parameters using cross-validation, optionally distributing the computation to several cores. This is accomplished by wrapping an estimator in a GridSearchCV object, where the “CV” stands for “cross-validated”. During the call to fit, it selects the parameters on a specified parameter grid, maximizing a score (the score method of the underlying estimator).','这是文章中的接口叙述，不是当前版本默认参数说明。')
fact('C8','GridSearchCV把predict、score或transform委托给调好参的估计器，因此仍能像普通估计器一样使用。',4,'predict, score, or transform are then delegated to the tuned estimator. This object can therefore be used transparently as any other estimator.')
fact('C9','Pipeline把多个transformer与一个estimator组成新estimator，例如先降维后拟合；GridSearchCV因此能调节各步骤的参数。',4,'Finally, a Pipeline object can combine several transformers and an estimator to create a combined estimator to, for example, apply dimension reduction before fitting. It behaves as a standard estimator, and GridSearchCV therefore tune the parameters of all steps.')
fact('C10','某些估计器可用热重启或正则化路径提高交叉验证效率，文中举LassoCV。',4,'Cross validation can be made more efficient for certain estimators by exploiting specific properties, such as warm restarts or regularization paths (Friedman et al., 2010). This is supported through special objects, such as the LassoCV.')
fact('C11','表1基准是Madelon：4400个实例、500个属性，作者称其足够大但多数算法仍可运行。',4,'We use the Madelon data set (Guyon et al., 2004), 4400 instances and 500 attributes, The data set is quite large, but small enough for most algorithms to run.','仅此数据规模，不是超大规模、流式输入或课程硬件性能实验。', '4400; 500')
fact('C12','表1指标为运行时间，单位秒；比较对象是当时可从Python访问的机器学习库。',4,'Table 1: Time in seconds on the Madelon data set for various machine learning libraries exposed in Python:','不是准确率、泛化能力或统计显著性比较。')
table=pages[4][pages[4].index('Support Vector Classification'):pages[4].index('Table 1:')]
fact('C13','优势比较：Madelon上Support Vector Classification，scikit-learn 5.2秒，mlpy 9.47秒，Shogun 5.63秒；该行还列PyBrain 17.5秒、pymvpa 11.52秒、MDP 40.48秒，scikit-learn在该行最短。',4,table,'表格文本抽取按列串接，算法与数值的对应关系已另对照out/table-page.png视觉核验；单位来自C12，数据来自C11。','5.2; 9.47; 5.63; 17.5; 11.52; 40.48')
fact('C14','反例：Madelon上k-Means（9簇），scikit-learn 1.34秒，mlpy 0.79秒，Shogun 0.68秒，后两者更快。PyBrain标星表示1小时内不收敛，不能当作普通秒值；横线表示未实现。',4,table,'视觉核验表格列/行；数据与单位同C11–C12。', '9; 1.34; 0.79; 0.68; 1')
fact('C15','另一个不占优势的比较：Madelon上k-Nearest Neighbors，scikit-learn 0.57秒，pymvpa 0.56秒。表中这个微小差异不构成跨环境稳定胜出的证据。',4,table,'视觉核验表格；未给重复次数或误差，不能由小数差推断显著性。','0.57; 0.56')
fact('C16','SVM相邻说明将性能归因于避免内存复制的绑定，以及对libsvm的稠密数据、内存占用、对齐和流水线等优化；这不是所有算法均最快的论据。',4,'First, our bindings avoid memory copies and have up to 40% less overhead than the original libsvm Python bindings. Second, we patch libsvm to improve efficiency on dense data, use a smaller memory footprint, and better use memory alignment and pipelining capabilities of modern processors.','40%是相对原始libsvm Python绑定的开销改善上限，不是表1全部算法的加速比。')
fact('C17','Elastic Net坐标下降在中等规模问题上与优化过的Fortran glmnet同一性能量级；超大问题受到限制，因为当时没有用KKT条件定义active set。',5,'It achieves the same order of performance as the highly optimized Fortran version glmnet (Friedman et al., 2010) on medium-scale problems, but performance on very large problems is limited since we do not use the KKT conditions to define an active set.','Elastic Net段；不是等速保证，更不是对当前实现的描述。')
fact('C18','当时k-means用纯Python实现，NumPy数组操作多次遍历数据限制了性能。',5,'scikit-learn’s k-means algorithm is implemented in pure Python. Its performance is limited by the fact that numpy’s array operations take multiple passes over data.','只描述论文时期实现；与表1反例一致，但不能推断今天仍如此。')
fact('C19','online learning在结论中列为未来工作，用于扩展到大数据集；本文不能用来证明当时已经实现并验证了超大规模在线训练。',5,'Future work includes online learning, to scale to large data sets.','未来方向是原文事实；不由此断言所有历史组件绝无增量行为。')
infer('I1','课程平台的统一模型接口与组合式实验组织在设计上适配；总体建议“需改造”，可将其作为选型候选和课程架构依据。',4,'It behaves as a standard estimator, and GridSearchCV therefore tune the parameters of all steps.','用户使用中等规模、可装入内存的表格数据，与C1定位接近；C2–C9让数据转换、训练、选参和评价能按统一约定组织。但课程数据类型、评分目标、划分策略和运行资源仍需课程自身确定，不能由接口一致性推出效果或速度保证。')
infer('I2','“所有算法都最快，而且适合超大规模在线训练”不能作为这篇文章的结论；若据此选型，该证据用途不可用。',5,'Future work includes online learning, to scale to large data sets.','C13只证明有限历史计时比较，C14–C15已有不占优势的反例；C17–C18限制可扩展性，C19把在线学习列作未来工作。故全称速度断言被反例否定，在线训练适配则未经本文验证。')
claims.append(dict(id='U1',**{'class':'UNKNOWN'},statement='所供2011年文章不能确定今天拟采用版本的API、实现、在线能力、依赖兼容性及性能。',value=None,absence_probe=['online learning','pure Python','release','GridSearchCV'],search_scope='仅INPUT/paper.pdf的6页正文和参考文献；没有仓库快照、当前文档或运行结果。',reasoning='命中的是历史设计、实现与未来计划，而非拟安装版本的证明。未联网、未执行模型，无法用历史时点跨越到当前版本。'))
claims.append(dict(id='U2',**{'class':'UNKNOWN'},statement='仅凭这6页，不能确定表1的完整硬件/软件版本、超参数、停止准则、重复测量误差及课程平台实际耗时。',value=None,absence_probe=['benchmark','seconds','processor','parameter','Madelon'],search_scope='所供PDF全部6页，重点表1、图注和第5节；未访问文中外部基准链接。',reasoning='上下文给了数据规模、秒值与部分实现解释，未给足以控制公平性及复算计时的完整配置。关键词命中并不补全这些信息；因此仅保留表内历史观察，不能推广成稳定排序。'))
doc=dict(paper=dict(title='Scikit-learn: Machine Learning in Python（Pedregosa等，JMLR 2011）',doi='',question='判断中等规模内存内表格数据的Python课程实验平台是否适配，并审查“所有算法最快、支持超大规模在线训练”的证据用途。',limitations_of_this_audit=['已提供：INPUT/task.md与6页PDF（期刊页2825–2830）；索引页数与任务相符，但页数检查本身不能证明材料完整。','未提供：代码仓库快照、当前版本文档、补充基准配置、课程数据和硬件规格。','只读所供材料；未联网、未运行模型、未复现实验。表1已对照页面图像确认列对应。']),claims=claims,parameters=[],derivations=[],coverage=[dict(item=item,status='covered',claim_ids=ids) for item,ids in [('estimator/transformer及数据接口',['C1','C2','C3','C4','C5']),('交叉验证、GridSearchCV、Pipeline',['C6','C7','C8','C9','C10']),('表1优势与反例、指标和条件',['C11','C12','C13','C14','C15','C16','U2']),('Elastic Net与k-means局限',['C17','C18']),('在线学习与历史/当前版本边界',['C19','I2','U1']),('课程适配与采用前补查',['I1','U1','U2'])]],transfer=[dict(step=s,verdict=v,because=b,needs=n) for s,v,b,n in [('统一模型接口的设计模式','可直接用',['C3','C4','C5'],'可直接借鉴接口思想；具体包版本调用仍需确认，不能要求所有模型提供全部方法。'),('内存内表格数据与预处理链','需改造',['C1','C2','C9','I1'],'确定缺失值、类别编码、尺度变换、稀疏表示与目标任务；检查整个搜索的内存预算。'),('参数选择与模型评估','需改造',['C6','C7','C8','C9'],'课程需明确评分指标与划分：建议将需学习参数的预处理放入每折训练流程，保留独立测试集或设计嵌套评估，避免选参成绩冒充最终泛化表现；这些是工程建议，非本文已验证的课程方案。'),('把本文作为所有算法最快及超大规模在线训练的证据','不可用',['C14','C15','C17','C18','C19','I2'],'改为有限历史基准的叙述；在线需求须另查具体版本、算法和数据访问方式。'),('今天版本的实际落地性能','信息不足',['U1','U2'],'锁定版本后查该版本官方API、用户指南、发布说明及实现；在课程硬件与代表性数据上另行验证。')]],verdict_overall='需改造',gaps=[dict(gap='缺拟采用版本资料',impact='不能承诺当前方法签名、实现语言或在线学习支持',close='采用前取得所选版本的官方estimator、Pipeline、GridSearchCV、增量学习文档、发布说明及依赖支持矩阵'),dict(gap='课程数据与评估规范未给定',impact='不能确认所有表格直接可用、评分是否公平或是否有泄漏',close='列明数据类型、样本/特征规模、分组或时间结构、标签、指标；审阅预处理在每个训练折拟合的行为，设置独立最终评估'),dict(gap='历史基准复算条件不足',impact='无法移植表1秒值或声称稳定速度排名',close='如需复核历史计时，取得当时基准脚本、库版本、硬件、超参数、停止条件和重复计时；课程采用前另安排代表性负载的耗时/峰值内存检查，本次不运行')],boundaries=['所有页码均为PDF从1开始的页码；PDF p.4对应期刊2828页，p.5对应2829页。','“可直接用”仅限可借鉴的设计模式；总体需改造不意味着现有材料已验证可直接部署。','表1的秒值是特定历史实验的计算时间，不能解释为预测精度、显著性或当前版本性能。'])
